import { Workflow, type WorkflowContext, type WorkflowRunner } from '@nestjs/workflows';

@Workflow('order-fulfilment')
export class OrderFulfilmentWorkflow implements WorkflowRunner<Order, FulfilmentResult> {
  constructor(
    private readonly paymentsService: PaymentsService,
    private readonly inventoryService: InventoryService,
  ) {}

  async run(ctx: WorkflowContext, order: Order): Promise<FulfilmentResult> {
    const charge = await ctx.step(
      'charge-payment',
      ({ idempotencyKey }) => this.paymentsService.charge(order, idempotencyKey),
      {
        retry: { attempts: 5, backoff: { delay: '2s' } },
        compensate: (charge, { idempotencyKey }) =>
          this.paymentsService.refund(charge.chargeId, idempotencyKey),
      },
    );

    await ctx.step('reserve-stock', ({ idempotencyKey }) =>
      this.inventoryService.reserve(order.items, idempotencyKey),
    );

    return { chargeId: charge.chargeId };
  }
}

import { Injectable } from '@nestjs/common';
import { Cron } from '@nestjs/schedule';
import { OnOneInstance, WithoutOverlapping } from '@nestjs/locks';

@Injectable()
export class StockReconciliationJob {
  @Cron(process.env.STOCK_RECONCILIATION_CRON ?? '*/5 * * * *', {
    name: 'stock-reconciliation',
  })
  @OnOneInstance({ key: 'inventory:stock-reconciliation' })
  @WithoutOverlapping()
  async reconcileStock() {
    // 只有租约持有者进入；长任务运行期间的 tick 被跳过
    const counts = await this.warehouse.fetchCounts();
    await this.stockRepository.writeCounts(counts);
  }
}

import { Controller, Get } from '@nestjs/common';
import {
  DiskHealthIndicator,
  HealthCheck,
  HealthCheckService,
  MemoryHealthIndicator,
  TypeOrmHealthIndicator,
} from '@nestjs/terminus';

@Controller('health')
export class HealthController {
  constructor(
    private readonly health: HealthCheckService,
    private readonly db: TypeOrmHealthIndicator,
    private readonly memory: MemoryHealthIndicator,
    private readonly disk: DiskHealthIndicator,
  ) {}

  @Get()
  @HealthCheck()
  check() {
    return this.health.check([
      () => this.db.pingCheck('database'),
      () => this.memory.checkHeap('memory_heap', 300 * 1024 * 1024),
      () => this.disk.checkStorage('disk', { path: '/', thresholdPercent: 0.5 }),
    ]);
  }
}

import { Injectable } from '@nestjs/common';
import { HealthIndicatorService } from '@nestjs/terminus';

@Injectable()
export class DogHealthIndicator {
  constructor(
    private readonly healthIndicatorService: HealthIndicatorService,
  ) {}

  isHealthy(key: string) {
    return this.healthIndicatorService
      .check(key)
      .attempt(async ({ signal }) => {
        const response = await fetch('https://dog.ceo/api/breeds/list', { signal });
        const { message: breeds } = await response.json();
        return { breeds: breeds.length };
      })
      .withTimeout(1000);
  }
}
